using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Runtime.InteropServices;
using System.Threading;
using IWshRuntimeLibrary;

namespace AppGroup {
    /// <summary>
    /// 用 UI Automation 判断“点在任务栏哪个按钮上”，并把它翻译成分组名。
    /// 背景：分组窗口已并入固定图标后，Windows 左键点击只会激活窗口、不会再启动快捷方式，
    /// 所以拿不到“用户点了分组图标”这个事件，只能自己监听鼠标 + 问任务栏这个按钮是谁。
    /// Win11 任务栏按钮的 UIA 元素：AutomationId = "Appid: &lt;AUMID&gt;"，Name = "&lt;分组名&gt; 已固定"。
    /// 本机 shell 属性系统损坏（读不出 .lnk 的 AUMID），固定按钮的 Appid 常常是 AutoGenerated 的，
    /// 因此还额外用“任务栏固定文件夹里的分组快捷方式名”做名称匹配兜底。
    /// </summary>
    internal static class TaskbarUia {

        // ---------------- COM: UI Automation ----------------

        [StructLayout(LayoutKind.Sequential)]
        private struct UiaRect { public int left, top, right, bottom; }

        [ComImport, Guid("30CBE57D-D9D0-452A-AB13-7AC5AC4825EE"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
        private interface IUIAutomation {
            void _CompareElements();
            void _CompareRuntimeIds();
            void _GetRootElement();
            void ElementFromHandle(IntPtr hwnd, [MarshalAs(UnmanagedType.Interface)] out IUIAutomationElement element);
            void _ElementFromPoint();
            void _GetFocusedElement();
            void _GetRootElementBuildCache();
            void _ElementFromHandleBuildCache();
            void _ElementFromPointBuildCache();
            void _GetFocusedElementBuildCache();
            void _CreateTreeWalker();
            void _get_ControlViewWalker();
            void _get_ContentViewWalker();
            void _get_RawViewWalker();
            void _get_RawViewCondition();
            void _get_ControlViewCondition();
            void _get_ContentViewCondition();
            void _CreateCacheRequest();
            void CreateTrueCondition([MarshalAs(UnmanagedType.Interface)] out object condition);
        }

        [ComImport, Guid("D22108AA-8AC5-49A5-837B-37BBB3D7591E"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
        private interface IUIAutomationElement {
            void _SetFocus();
            void _GetRuntimeId();
            void _FindFirst();
            [return: MarshalAs(UnmanagedType.Interface)]
            IUIAutomationElementArray FindAll(int scope, [MarshalAs(UnmanagedType.Interface)] object condition);
            void _FindFirstBuildCache();
            void _FindAllBuildCache();
            void _BuildUpdatedCache();
            void _GetCurrentPropertyValue();
            void _GetCurrentPropertyValueEx();
            void _GetCachedPropertyValue();
            void _GetCachedPropertyValueEx();
            void _GetCurrentPatternAs();
            void _GetCachedPatternAs();
            void _GetCurrentPattern();
            void _GetCachedPattern();
            void _GetCachedParent();
            void _GetCachedChildren();
            void _get_CurrentProcessId();
            int get_CurrentControlType();
            void _get_CurrentLocalizedControlType();
            [return: MarshalAs(UnmanagedType.BStr)]
            string get_CurrentName();
            void _get_CurrentAcceleratorKey();
            void _get_CurrentAccessKey();
            void _get_CurrentHasKeyboardFocus();
            void _get_CurrentIsKeyboardFocusable();
            void _get_CurrentIsEnabled();
            [return: MarshalAs(UnmanagedType.BStr)]
            string get_CurrentAutomationId();
            [return: MarshalAs(UnmanagedType.BStr)]
            string get_CurrentClassName();
            void _get_CurrentHelpText();
            void _get_CurrentCulture();
            void _get_CurrentIsControlElement();
            void _get_CurrentIsContentElement();
            void _get_CurrentIsPassword();
            void _get_CurrentNativeWindowHandle();
            void _get_CurrentItemType();
            void _get_CurrentIsOffscreen();
            void _get_CurrentOrientation();
            void _get_CurrentFrameworkId();
            void _get_CurrentIsRequiredForForm();
            void _get_CurrentItemStatus();
            UiaRect get_CurrentBoundingRectangle();
        }

        [ComImport, Guid("14314595-B4BC-4055-95F2-58F2E42C9855"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
        private interface IUIAutomationElementArray {
            int get_Length();
            [return: MarshalAs(UnmanagedType.Interface)]
            IUIAutomationElement GetElement(int index);
        }

        private const int TreeScope_Descendants = 0x4;
        private const int UIA_ButtonControlType = 50000;

        [DllImport("ole32.dll")]
        private static extern int CoInitializeEx(IntPtr pv, uint coInit);

        [DllImport("ole32.dll")]
        private static extern void CoUninitialize();

        private static readonly Guid ClsidCUIAutomation = new Guid("FF48DBA4-60EF-4201-AA87-54103EEF594E");

        // ---------------- 对外接口 ----------------

        /// <summary>返回点击点所在任务栏按钮对应的分组名；不是分组图标则返回 null。</summary>
        public static string IdentifyGroupAt(NativeMethods.POINT physicalPoint) {
            string result = null;
            try {
                var t = new Thread(() => {
                    try { result = IdentifyCore(physicalPoint); }
                    catch (Exception ex) { Debug.WriteLine($"[TaskbarUia] {ex.Message}"); }
                });
                t.SetApartmentState(ApartmentState.STA);
                t.IsBackground = true;
                t.Start();
                t.Join(800);
            }
            catch (Exception ex) {
                Debug.WriteLine($"[TaskbarUia] thread failed: {ex.Message}");
            }
            return result;
        }

        private static string IdentifyCore(NativeMethods.POINT physicalPoint) {
            int hr = CoInitializeEx(IntPtr.Zero, 2 /*COINIT_APARTMENTTHREADED*/);
            try {
                var uiaType = Type.GetTypeFromCLSID(ClsidCUIAutomation);
                if (uiaType == null) return null;
                var uia = (IUIAutomation)Activator.CreateInstance(uiaType);

                object condition;
                uia.CreateTrueCondition(out condition);

                foreach (IntPtr tbHwnd in GetTaskbarWindows()) {
                    if (!NativeMethods.GetWindowRect(tbHwnd, out NativeMethods.RECT wr)) continue;
                    if (physicalPoint.X < wr.left || physicalPoint.X >= wr.right ||
                        physicalPoint.Y < wr.top || physicalPoint.Y >= wr.bottom) continue;

                    IUIAutomationElement tbEl;
                    uia.ElementFromHandle(tbHwnd, out tbEl);
                    if (tbEl == null) continue;

                    // UIA 返回的坐标可能被 DPI 缩放（取决于调用进程的 DPI 感知），这里按任务栏矩形自校准
                    var tbr = tbEl.get_CurrentBoundingRectangle();
                    double scaleX = (wr.right - wr.left) > 0 && (tbr.right - tbr.left) > 0
                        ? (double)(tbr.right - tbr.left) / (wr.right - wr.left) : 1.0;
                    double scaleY = (wr.bottom - wr.top) > 0 && (tbr.bottom - tbr.top) > 0
                        ? (double)(tbr.bottom - tbr.top) / (wr.bottom - wr.top) : 1.0;
                    int ux = tbr.left + (int)Math.Round((physicalPoint.X - wr.left) * scaleX);
                    int uy = tbr.top + (int)Math.Round((physicalPoint.Y - wr.top) * scaleY);

                    var buttons = tbEl.FindAll(TreeScope_Descendants, condition);
                    if (buttons == null) continue;
                    int count = buttons.get_Length();
                    for (int i = 0; i < count; i++) {
                        var btn = buttons.GetElement(i);
                        if (btn == null) continue;
                        if (btn.get_CurrentControlType() != UIA_ButtonControlType) continue;
                        var r = btn.get_CurrentBoundingRectangle();
                        if (ux < r.left || ux >= r.right || uy < r.top || uy >= r.bottom) continue;
                        string group = MapButtonToGroup(btn);
                        TaskbarDebugLog.Write(
                            $"uia hit btn name='{btn.get_CurrentName()}' aid='{btn.get_CurrentAutomationId()}' " +
                            $"uiaRect=({r.left},{r.top})-({r.right},{r.bottom}) ui=({ux},{uy}) scale={scaleX:0.###} -> '{group ?? "(null)"}'");
                        if (!string.IsNullOrEmpty(group)) return group;
                        // 点在了任务栏按钮上但不是分组图标：明确不做任何事（避免误弹）
                        return null;
                    }
                }
            }
            finally {
                if (hr >= 0) CoUninitialize();
            }
            return null;
        }

        private static IEnumerable<IntPtr> GetTaskbarWindows() {
            var list = new List<IntPtr>();
            IntPtr h = NativeMethods.FindWindow("Shell_TrayWnd", null);
            if (h != IntPtr.Zero) list.Add(h);
            // 多显示器时每块副屏还有一个 Shell_SecondaryTrayWnd
            IntPtr prev = IntPtr.Zero;
            while (true) {
                IntPtr next = NativeMethods.FindWindowEx(IntPtr.Zero, prev, "Shell_SecondaryTrayWnd", null);
                if (next == IntPtr.Zero) break;
                list.Add(next);
                prev = next;
            }
            return list;
        }

        private static string MapButtonToGroup(IUIAutomationElement btn) {
            string aid = btn.get_CurrentAutomationId() ?? string.Empty;
            const string appIdPrefix = "Appid: ";
            const string groupAumidPrefix = "AppGroup.Group.";
            if (aid.StartsWith(appIdPrefix, StringComparison.OrdinalIgnoreCase)) {
                string aumid = aid.Substring(appIdPrefix.Length).Trim();
                if (aumid.StartsWith(groupAumidPrefix, StringComparison.OrdinalIgnoreCase) &&
                    aumid.Length > groupAumidPrefix.Length)
                    return aumid.Substring(groupAumidPrefix.Length);
            }

            string name = btn.get_CurrentName() ?? string.Empty;
            if (name.Length == 0) return null;

            string bestGroup = null;
            int bestLen = -1;
            foreach (var pinned in GetPinnedGroups()) {
                if (pinned.ShortcutName.Length <= bestLen) continue;
                bool matched = name.Equals(pinned.ShortcutName, StringComparison.OrdinalIgnoreCase) ||
                    (name.Length > pinned.ShortcutName.Length &&
                     name.StartsWith(pinned.ShortcutName, StringComparison.OrdinalIgnoreCase) &&
                     !char.IsLetterOrDigit(name[pinned.ShortcutName.Length]));
                if (!matched) continue;
                bestLen = pinned.ShortcutName.Length;
                bestGroup = pinned.GroupName;
            }
            return bestGroup;
        }

        // ---------------- 任务栏固定目录里的“分组快捷方式” ----------------

        private sealed class PinnedGroupInfo {
            public string ShortcutName;   // 任务栏按钮显示名（= 快捷方式文件名，不含 .lnk）
            public string GroupName;
        }

        private static List<PinnedGroupInfo> _pinnedGroups;
        private static DateTime _pinnedGroupsLoadedAt = DateTime.MinValue;

        private static List<PinnedGroupInfo> GetPinnedGroups() {
            if (_pinnedGroups != null && (DateTime.UtcNow - _pinnedGroupsLoadedAt).TotalSeconds < 10)
                return _pinnedGroups;

            var list = new List<PinnedGroupInfo>();
            try {
                string dir = Path.Combine(
                    Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
                    @"Microsoft\Internet Explorer\Quick Launch\User Pinned\TaskBar");
                string exePath = Environment.ProcessPath ?? Process.GetCurrentProcess().MainModule?.FileName;
                if (Directory.Exists(dir) && !string.IsNullOrEmpty(exePath)) {
                    IWshShell wsh = new WshShell();
                    try {
                        foreach (string file in Directory.EnumerateFiles(dir, "*.lnk")) {
                            try {
                                IWshShortcut sc = (IWshShortcut)wsh.CreateShortcut(file);
                                if (!string.Equals(sc.TargetPath ?? "", exePath, StringComparison.OrdinalIgnoreCase)) continue;
                                string group = ParseGroupName(sc.Arguments, sc.Description);
                                if (string.IsNullOrEmpty(group)) continue;
                                list.Add(new PinnedGroupInfo {
                                    ShortcutName = Path.GetFileNameWithoutExtension(file),
                                    GroupName = group
                                });
                            }
                            catch { }
                        }
                    }
                    finally { Marshal.ReleaseComObject(wsh); }
                }
            }
            catch (Exception ex) {
                Debug.WriteLine($"[TaskbarUia] read pinned shortcuts failed: {ex.Message}");
            }

            _pinnedGroups = list;
            _pinnedGroupsLoadedAt = DateTime.UtcNow;
            return list;
        }

        /// <summary>分组固定快捷方式的参数形如 "Editor"；描述形如 "Editor - AppGroup Shortcut"。</summary>
        private static string ParseGroupName(string arguments, string description) {
            string args = (arguments ?? string.Empty).Trim();
            if (args.Length > 0) {
                if (args[0] == '"') {
                    int end = args.IndexOf('"', 1);
                    if (end > 1) return args.Substring(1, end - 1);
                }
                int sp = args.IndexOf(' ');
                string token = sp > 0 ? args.Substring(0, sp) : args;
                if (token.Length > 0) return token;
            }
            const string suffix = "- AppGroup Shortcut";
            string desc = (description ?? string.Empty).Trim();
            if (desc.EndsWith(suffix, StringComparison.OrdinalIgnoreCase))
                return desc.Substring(0, desc.Length - suffix.Length).Trim();
            return null;
        }
    }
}
